			title = "Resumo",
			text = [=[Baristolth das Areias Cambiantes está no {link:cenarion-hold}Forte Cenariano{/link} e olha para as colmeias. Há mil anos ele jazia mutilado e à beira da morte. Um grande ser soprou uma única vez sobre seu corpo e esperou enquanto as areias do tempo curavam suas feridas. Então Baristolth foi obrigado a permanecer como vigia por tanto tempo quanto fosse preciso. Sua vigília dura desde então.]=],
		},
		{
			title = "Importância",
			text = [=[Baristolth é um fio vivo que leva à velha guerra. Fez uma promessa há mil anos, e acredita que chegou a hora de cumpri-la. Sente a terra tremer em volta das colmeias, e sabe que os {link:qiraji}Qiraji{/link} se preparam para a guerra.]=],
		},
		{
			title = "Feitos",
			text = [=[• Foi salvo da morte e obrigado a servir como vigia.
• Vigia as colmeias e sente a terra estremecer enquanto os {link:qiraji}Qiraji{/link} planejam a guerra.
• Envia mensagem às {link:caverns-of-time}Cavernas do Tempo{/link}, para saber se seu mestre voltou.]=],
		},
		{
			title = "Sem Registro",
			text = [=[Nenhum registro diz de que povo Baristolth vem, nem como era sua vida antes de ser obrigado à vigília.]=],
		},
	},
	chapters = {
		{
			title = "O Que o Amanhã Traz",
			hint = "Busque para o vigia o lugar de repouso dos dragões bronze.",
			text = [=[Baristolth não podia agir até saber uma coisa: se o mestre que o salvou havia voltado ao mundo. Enviou um mensageiro às {link:caverns-of-time}Cavernas do Tempo{/link}, em {link:tanaris}Tanaris{/link}, para encontrar Anachronos, da prole de {red:nozdormu}Nozdormu{/red}. Quando a resposta veio, disse que tudo estava como devia ser. O grande havia se erguido, e sua longa vigília chegava ao fim. Uma segunda guerra estava a caminho do deserto.]=],
		},
	},
	mentions = {
		{ text = "O Que o Amanhã Traz" },
	},
	bonds = {
		{ id = "anachronos", name = "Anachronos", note = "o mestre por quem espera" },
		{ id = "ralo-shan-the-eternal-watcher", name = "Ralo'shan, o Vigia Eterno", note = "outro que restou da velha guerra" },
		{ id = "commander-mar-alith", name = "Comandante Mar'alith", note = "divide com ele o Forte" },
	},
})

Translate("ptBR", "geologist-larksbane", {
	title = "Geóloga Larksbane",
	subtitle = "Estudiosa do Forte Cenariano",
	found = "Forte Cenariano",
	hint = "Fale com a geóloga que escuta o zumbido do deserto.",
	allegiance = "Círculo Cenariano",
	aliases = { "Larksbane" },
	sections = {
		{
			title = "Resumo",
			text = [=[A Geóloga Larksbane estuda as pedras e os cristais de {link:silithus}Silithus{/link} para o {link:cenarion-circle}Círculo Cenariano{/link}. Ela ouve no deserto um zumbido que fica mais alto a cada dia, e tem certeza de que os cristais das colmeias são o que enlouquece os silitídeos. Seu trabalho a leva das ruínas de um acampamento do {link:twilight-s-hammer}Martelo do Crepúsculo{/link} aos ossos de um dragão morto.]=],
		},
		{
			title = "Importância",
			text = [=[Onde os soldados só veem inimigos a matar, Larksbane vê mensagens a ler. Ela rompeu o silêncio dos cristais glifados. A chave que buscava, acredita ela, guarda vinte mil anos de história.]=],
		},
		{
			title = "Feitos",
			text = [=[• Reuniu a tabuleta partida de um acampamento arruinado do culto e a enviou a um desertor para ser lida.
• Descobriu como os cristais glifados das colmeias transmitem suas mensagens.
• Traçou os glifos que poderiam tirar um emissário {link:qiraji}Qiraji{/link} do esconderijo.]=],
		},
	},
	chapters = {
		{
			title = "O Mistério do Crepúsculo",
			hint = [=[Reúna a tabuleta partida do acampamento devastado no noroeste.]=],
			text = [=[A tabuleta do acampamento devastado não fazia sentido. Cada palavra podia ser lida, mas juntas as palavras nada significavam. Larksbane sabia que as seitas do {link:twilight-s-hammer}Martelo do Crepúsculo{/link} às vezes escrevem em código. Boatos falavam de um cultista chamado {link:hermit-ortell}Ortell{/link} que fugira de sua ordem e vivia como eremita nas montanhas. Se alguém podia lê-la, era ele.]=],
		},
		{
			title = "O Prisma Glifado",
			hint = [=[Leve a ela o prisma que os anões fizeram com as cópias das colmeias.]=],
			text = [=[Os anões haviam copiado os glifos das três colmeias num prisma de cristal, mas não conseguiam ler nada. Larksbane viu por quê. Não havia nada a ler na superfície. A camada externa do prisma precisava girar e se alinhar às marcas do cristal interno para que qualquer mensagem passasse. Só uma pista restava em sua face, e ela parecia sombria.]=],
		},
		{
			title = "O Chamado",
			hint = "Desenhe os glifos de chamado nos Ossos de Grakkarond.",
			text = [=[Os glifos mostravam um emissário {link:qiraji}Qiraji{/link} encontrando três senhores das colmeias junto aos ossos de um dragão. Larksbane copiou o código acima deles. Desenhado na areia nos {link:bones-of-grakkarond}Ossos de Grakkarond{/link}, ele traria os senhores supremos, e o emissário atrás deles, que guardava a chave dos cristais. Quando essa chave foi posta em suas mãos, ela disse que segurava vinte mil anos de história.]=],
		},
	},
	mentions = {
		{ text = "O Mistério do Crepúsculo" },
		{ text = "O Desertor" },
		{ text = "Desvendando o Mistério" },
		{ text = "O Chamado" },
	},
	bonds = {
		{ id = "hermit-ortell", name = "Eremita Ortell", note = "lê o código do culto" },
		{ id = "rutgar-glyphshaper", name = "Rutgar Glyphshaper", note = "copiou os glifos" },
		{ id = "commander-mar-alith", name = "Comandante Mar'alith", note = "seu comandante" },
	},
})

