Translate("ptBR", "twilight-lord-everun", {
	title = "Senhor do Crepúsculo Everun",
	subtitle = "Senhor do Martelo do Crepúsculo",
	found = "Os acampamentos do culto no oeste de Silithus",
	hint = [=[Enfrente o Senhor do Crepúsculo que é visto nos acampamentos do culto.]=],
	allegiance = "Martelo do Crepúsculo",
	aliases = { "Everun" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Senhor do Crepúsculo Everun é um dos senhores do {link:twilight-s-hammer}Martelo do Crepúsculo{/link} em {link:silithus}Silithus{/link}. Ele aparece nos acampamentos do culto no oeste e envia suas ordens aos fiéis. Acima de tudo, quer que o desertor {link:hermit-ortell}Ortell{/link} seja encontrado. Seus boletins avisam que quem esconder o que sabe sobre o traidor será punido.]=],
		},
